  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    // Use URLSearchParams to send data as application/x-www-form-urlencoded
    // This is the most reliable way to populate e.parameter in Google Apps Script
    const formData = new URLSearchParams();
    formData.append('author', newReview.author);
    formData.append('email', newReview.email);
    formData.append('rating', newReview.rating.toString());
    formData.append('comment', newReview.comment);
    formData.append('productId', product.id);
    formData.append('productName', product.name);
    formData.append('timestamp', new Date().toISOString());

    try {
      await fetch('https://script.google.com/macros/s/AKfycbwb_66BBdIY1z4rUHd0sg3G1k0D2LFTIgqsJxwi1Vfwik5s0lK3NEaTsd-aAky-G-Yp/exec', {
        method: 'POST',
        mode: 'no-cors', // Essential for GAS calls from browser
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: formData.toString(),
      });

      // Update local reviews list for immediate feedback
      const review: Review = {
        id: Math.random().toString(36).substr(2, 9),
        author: newReview.author || 'Anonymous',
        rating: newReview.rating,
        comment: newReview.comment,
        email: newReview.email,
        date: 'Just now'
      };

      setReviews([review, ...reviews]);
      setSubmitted(true);

      setTimeout(() => {
        setSubmitted(false);
        setIsFormOpen(false);
        setNewReview({ author: '', email: '', rating: 5, comment: '' });
      }, 3000);
    } catch (error) {
      console.error('Error submitting feedback:', error);
      alert('There was an issue sending your feedback. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="mt-24 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24 border-t border-gray-200">
