Copy and paste this into your Google Apps Script editor (`Code.gs`).
**Important:** After saving the code, you must click **Deploy > New Deployment**, select type "Web App", set "Who has access" to **"Anyone"**, and click Deploy. If you don't do this, the script won't update to the new logic.

### Google Apps Script (Code.gs)

```javascript
function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    var doc = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = doc.getSheetByName('Sheet1'); // Ensure your sheet is named 'Sheet1' or change this

    // If sheet doesn't exist, create it and add headers
    if (!sheet) {
      sheet = doc.insertSheet('Sheet1');
      sheet.appendRow(['Date', 'Author', 'Email', 'Rating', 'Comment', 'Product']);
    }

    var data;

    // Handle JSON data sent as text/plain (Recommended method)
    if (e.postData && e.postData.contents) {
      try {
        data = JSON.parse(e.postData.contents);
      } catch (err) {
        // Fallback if parsing fails
        data = e.parameter;
      }
    } else {
      // Fallback for form-urlencoded
      data = e.parameter;
    }

    var timestamp = new Date();
    var author = data.author;
    var email = data.email;
    var rating = data.rating;
    var comment = data.comment;
    var productName = data.productName;

    // Append the row
    sheet.appendRow([timestamp, author, email, rating, comment, productName]);

    return ContentService
      .createTextOutput(JSON.stringify({ 'result': 'success', 'row': sheet.getLastRow() }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService
      .createTextOutput(JSON.stringify({ 'result': 'error', 'error': e.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}
```

### Frontend Update

I am updating your frontend code to send the data as **JSON** with a `text/plain` header. This is the most reliable way to bypass CORS preflight issues with Google Apps Script.

