        method: 'POST',
        mode: 'no-cors', // Essential for Google Apps Script
        headers: {
          'Content-Type': 'text/plain', 
        },
        body: JSON.stringify(payload),
      });

      // Show alert on success as requested
      alert('Thank you!');

      // Add to local UI reviews list for immediate feedback
      const review: Review = {
        id: Math.random().toString(36).substr(2, 9),
        author: newReview.name || 'Anonymous',
        email: newReview.email,
        rating: newReview.rating,
        comment: newReview.comment,
        date: 'Just now'
      };

      setReviews([review, ...reviews]);
      setSubmitted(true);

      setTimeout(() => {
        setSubmitted(false);
        setIsFormOpen(false);
        setNewReview({ name: '', email: '', rating: 5, comment: '' });
      }, 3000);
    } catch (error) {
      console.error('Submission error:', error);
      alert('There was a problem submitting your feedback. Please try again.');
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="mt-24 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24 border-t border-gray-200">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 mb-16">
