            left: `${dot.left}%`,
            top: `${dot.top}%`,
            opacity: dot.opacity,
            '--duration': `${dot.duration}s`,
            animationDelay: `${dot.delay}s`
          } as React.CSSProperties}
        />
      ))}
    </div>
  );
};

