const FeedbackSection: React.FC<{ product: Product }> = ({ product }) => {
  const [reviews, setReviews] = useState<Review[]>(product.reviews || []);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [newReview, setNewReview] = useState({ name: '', email: '', rating: 5, comment: '' });
  const [isSending, setIsSending] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSending(true);

    // Capture values into a JSON object with requested keys
    const payload = {
      name: newReview.name,
      email: newReview.email,
      rating: newReview.rating, // numeric 1-5
      comment: newReview.comment
    };

    try {
      // Intercept form submission and send as POST request to Google Apps Script
      // Using 'no-cors' mode as standard for Google Apps Script Web Apps when triggered from direct browser fetch
      await fetch('https://script.google.com/macros/s/AKfycbyJ98hv2-18NDmYkPGQpXc31mDBOutX4bb-zK_Lk0ggy5ipNdsMtkp536hi6LmTfrWKsw/exec', {
        method: 'POST',
        mode: 'no-cors', 
        headers: {
          'Content-Type': 'text/plain', // Use text/plain for simple POST that bypasses CORS preflight
        },
        body: JSON.stringify(payload),
      });

      // Show alert saying 'Thank you!' upon success
      alert('Thank you!');

      // Locally update UI for immediate feedback
      const review: Review = {
        id: Math.random().toString(36).substr(2, 9),
        author: newReview.name || 'Anonymous',
        email: newReview.email,
        rating: newReview.rating,
        comment: newReview.comment,
        date: 'Just now'
      };

      setReviews([review, ...reviews]);
      setSubmitted(true);

      setTimeout(() => {
        setSubmitted(false);
        setIsFormOpen(false);
        setNewReview({ name: '', email: '', rating: 5, comment: '' });
      }, 3000);
    } catch (error) {
      console.error('Error submitting feedback:', error);
