const Checkout: React.FC = () => {
  const { cart, cartTotal, clearCart } = useCart();
  const navigate = useNavigate();

  const [isProcessing, setIsProcessing] = useState(false);
  const [currency, setCurrency] = useState<Currency>('EUR');
  const [checkoutUrl, setCheckoutUrl] = useState<string | null>(null);
  const [orderId, setOrderId] = useState<string | null>(null);
  const [paymentStatus, setPaymentStatus] = useState<'pending' | 'paid' | null>(null);
  const [isPolling, setIsPolling] = useState(false);
  const [pollError, setPollError] = useState<string | null>(null);

  const [shippingInfo, setShippingInfo] = useState({
    fullName: '',
    email: '',
    street: '',
    city: '',
    zip: '',
    country: 'Netherlands'
  });

  const APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbztHTV2k3Q3mcKvgrjF4E6Nca7m0ex_-430j1cMCql0W-oXG6rouLDLccL2QWSsARjlBw/exec';

  const currencyMap = {
    EUR: { symbol: '€', rate: 1 },
    USD: { symbol: '$', rate: 1.08 },
    GBP: { symbol: '£', rate: 0.83 },
    JPY: { symbol: '¥', rate: 162.5 }
  };

  const currentTotal = useMemo(() => {
    return cartTotal * currencyMap[currency].rate;
  }, [cartTotal, currency]);

  const formattedTotal = useMemo(() => {
    return currentTotal.toFixed(2);
  }, [currentTotal]);

  const handlePayment = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    setPollError(null);

    const payload = {
      customerName: shippingInfo.fullName,
      email: shippingInfo.email,
      address: {
        street: shippingInfo.street,
        city: shippingInfo.city,
        zip: shippingInfo.zip,
        country: shippingInfo.country
      },
      items: cart.map(item => ({
        name: item.name,
        quantity: item.quantity,
        price: item.price * currencyMap[currency].rate
      })),
      currency: currency,
      totalAmount: formattedTotal
    };

    try {
      const response = await fetch(APPS_SCRIPT_URL, {
        method: 'POST',
        mode: 'cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload),
      });

      const result = await response.json();

      if (result.checkoutUrl) {
        setCheckoutUrl(result.checkoutUrl);
        setOrderId(result.orderId || `ORD-${Date.now()}`);
        // Sandbox safe redirect using new tab
        window.open(result.checkoutUrl, '_blank');
      } else {
        throw new Error('No checkout URL received');
      }
    } catch (error) {
      console.error('Payment Error:', error);
      setPollError('Payment initialization failed. Please check your connection and try again.');
    } finally {
      setIsProcessing(false);
    }
  };

  const checkStatus = async () => {
    if (!orderId) return;
    setIsPolling(true);
    setPollError(null);
    try {
      const response = await fetch(`${APPS_SCRIPT_URL}?orderId=${orderId}`, {
        method: 'GET',
        mode: 'cors'
      });
      const result = await response.json();
      if (result.status === 'paid') {
        setPaymentStatus('paid');
        clearCart();
        setTimeout(() => navigate('/success'), 2000);
      } else if (result.status === 'open' || result.status === 'pending') {
        setPollError('Payment is still pending. Please ensure you have completed the transaction in the payment window.');
      } else if (result.status === 'failed' || result.status === 'expired' || result.status === 'canceled') {
        setPollError(`Payment ${result.status}. The order could not be completed. Please try again or contact support.`);
      } else {
        setPollError('Payment status could not be confirmed yet. Please complete the transaction.');
      }
    } catch (error) {
      console.error('Status Check Error:', error);
      setPollError('Could not verify payment status due to a connection error. Please try clicking the button again.');
    } finally {
      setIsPolling(false);
    }
  };

  if (cart.length === 0 && !orderId) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col">
        <Header />
        <div className="flex-1 flex flex-col items-center justify-center p-8">
          <ShoppingCart className="h-24 w-24 text-gray-300 mb-8" />
          <p className="text-3xl font-black text-gray-600 mb-8">Your cart is empty.</p>
          <button onClick={() => navigate('/')} className="text-[#FDB623] font-black text-2xl hover:underline">Start Shopping</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      <Header />
      <div className="max-w-6xl mx-auto px-4 py-16">
        <button onClick={() => navigate('/')} className="flex items-center text-gray-500 hover:text-gray-900 mb-12 text-xl font-bold transition-colors">
          <ChevronLeft className="h-7 w-7 mr-2" /> Back to Catalog
        </button>

        <div className="flex flex-col lg:flex-row gap-16 items-start">
          <div className="flex-1 w-full space-y-12">
            {!checkoutUrl ? (
              <>
                <div>
                  <h1 className="text-6xl font-black mb-4">Checkout</h1>
                  <p className="text-2xl text-gray-500 font-bold">Secure payment for your QrSortable kit</p>
                </div>

                <div className="bg-white rounded-[2rem] p-8 shadow-sm border border-gray-100">
                  <div className="flex items-center justify-between">
                    <h2 className="text-3xl font-black flex items-center">
                      <Globe className="h-8 w-8 mr-3 text-[#FDB623]" /> Currency
                    </h2>
                    <select 
                      value={currency}
                      onChange={(e) => setCurrency(e.target.value as Currency)}
                      className="bg-gray-100 border-none rounded-2xl p-4 text-xl font-black outline-none focus:ring-4 focus:ring-[#FDB623]/20 appearance-none pr-10 cursor-pointer"
                    >
                      <option value="EUR">EUR (€)</option>
                      <option value="USD">USD ($)</option>
                      <option value="GBP">GBP (£)</option>
                    </select>
                  </div>
                </div>

                <form id="checkout-form" onSubmit={handlePayment} className="space-y-10">
                  <div className="bg-white rounded-[3rem] p-10 shadow-sm border border-gray-100">
                    <h2 className="text-3xl font-black mb-10 flex items-center">
                      <MapPin className="h-8 w-8 mr-4 text-[#FDB623]" /> Shipping
                    </h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      <div className="space-y-3">
                        <label className="text-lg font-black block">Full Name</label>
                        <input type="text" placeholder="John Doe" required value={shippingInfo.fullName} onChange={e => setShippingInfo({...shippingInfo, fullName: e.target.value})} className="w-full border-2 border-gray-100 bg-gray-50 rounded-2xl p-5 text-xl font-bold outline-none focus:ring-4 focus:ring-[#FDB623]/20" />
                      </div>
                      <div className="space-y-3">
                        <label className="text-lg font-black block">Email Address</label>
                        <input type="email" placeholder="john@example.com" required value={shippingInfo.email} onChange={e => setShippingInfo({...shippingInfo, email: e.target.value})} className="w-full border-2 border-gray-100 bg-gray-50 rounded-2xl p-5 text-xl font-bold outline-none focus:ring-4 focus:ring-[#FDB623]/20" />
                      </div>
                      <div className="md:col-span-2 space-y-3">
                        <label className="text-lg font-black block">Street & Number</label>
                        <input type="text" placeholder="Main St 123" required value={shippingInfo.street} onChange={e => setShippingInfo({...shippingInfo, street: e.target.value})} className="w-full border-2 border-gray-100 bg-gray-50 rounded-2xl p-5 text-xl font-bold outline-none focus:ring-4 focus:ring-[#FDB623]/20" />
                      </div>
                      <div className="space-y-3">
                        <label className="text-lg font-black block">City</label>
                        <input type="text" placeholder="Amsterdam" required value={shippingInfo.city} onChange={e => setShippingInfo({...shippingInfo, city: e.target.value})} className="w-full border-2 border-gray-100 bg-gray-50 rounded-2xl p-5 text-xl font-bold outline-none focus:ring-4 focus:ring-[#FDB623]/20" />
                      </div>
                      <div className="grid grid-cols-2 gap-5">
                        <div className="space-y-3">
                          <label className="text-lg font-black block">ZIP</label>
                          <input type="text" placeholder="1011 AB" required value={shippingInfo.zip} onChange={e => setShippingInfo({...shippingInfo, zip: e.target.value})} className="w-full border-2 border-gray-100 bg-gray-50 rounded-2xl p-5 text-xl font-bold outline-none focus:ring-4 focus:ring-[#FDB623]/20" />
                        </div>
                        <div className="space-y-3">
                          <label className="text-lg font-black block">Country</label>
                          <input type="text" placeholder="Netherlands" required value={shippingInfo.country} onChange={e => setShippingInfo({...shippingInfo, country: e.target.value})} className="w-full border-2 border-gray-100 bg-gray-50 rounded-2xl p-5 text-xl font-bold outline-none focus:ring-4 focus:ring-[#FDB623]/20" />
                        </div>
                      </div>
                    </div>
                  </div>
                  {pollError && (
                    <div className="bg-red-50 border-2 border-red-100 p-8 rounded-3xl flex items-start space-x-4 animate-in shake duration-300">
                      <AlertCircle className="h-8 w-8 text-red-500 flex-shrink-0 mt-1" />
                      <div>
                        <p className="text-red-900 font-black text-xl mb-1">Initialization Failed</p>
                        <p className="text-red-700 font-bold text-lg leading-relaxed">{pollError}</p>
                      </div>
                    </div>
                  )}
                </form>
              </>
            ) : (
              <div className="bg-white rounded-[3rem] p-12 shadow-2xl border-4 border-[#FDB623]/20 text-center space-y-10 animate-in fade-in duration-500">
                <div className="bg-[#FDB623]/10 w-32 h-32 rounded-full flex items-center justify-center mx-auto">
                   {paymentStatus === 'paid' ? (
                     <Check className="h-16 w-16 text-green-500" />
