                      : "Please complete your payment in the secure window we opened for you. If it doesn’t open, click ‘Payment page not opening? Click here’ below."}
                  </p>
                </div>

                {pollError && (
                  <div className="bg-red-50 border-2 border-red-100 p-8 rounded-3xl flex items-start space-x-4 animate-in slide-in-from-top-4 duration-300 text-left">
