            <span className="text-4xl font-bold text-[#FDB623] tracking-tighter">QrSortable</span>
          </div>

          <div className="hidden md:flex space-x-12 items-center">
            {navLinks.map((link) => (
              <button 
                key={link.name} 
                onClick={() => handleNavClick(link.href)}
