const Checkout: React.FC = () => {
  const { cart, cartTotal, clearCart } = useCart();
  const navigate = useNavigate();

  const [isProcessing, setIsProcessing] = useState(false);
  const [currency, setCurrency] = useState<Currency>('EUR');
  const [checkoutUrl, setCheckoutUrl] = useState<string | null>(null);
  const [orderId, setOrderId] = useState<string | null>(null);
  const [paymentStatus, setPaymentStatus] = useState<'pending' | 'paid' | null>(null);
  const [isPolling, setIsPolling] = useState(false);
  const [pollError, setPollError] = useState<string | null>(null);

  const [shippingInfo, setShippingInfo] = useState({
    fullName: '',
    email: '',
    street: '',
    city: '',
    zip: '',
    country: ''
  });

  const APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbztHTV2k3Q3mcKvgrjF4E6Nca7m0ex_-430j1cMCql0W-oXG6rouLDLccL2QWSsARjlBw/exec';

  const currencyMap = {
    EUR: { symbol: '€', rate: 1 },
    USD: { symbol: '$', rate: 1.08 },
    GBP: { symbol: '£', rate: 0.83 },
    JPY: { symbol: '¥', rate: 162.5 }
  };

  const currentTotal = useMemo(() => {
    return cartTotal * currencyMap[currency].rate;
  }, [cartTotal, currency]);

  const formattedTotal = useMemo(() => {
    return currentTotal.toFixed(2);
  }, [currentTotal]);

  const handlePayment = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    setPollError(null);

    const payload = {
      customerName: shippingInfo.fullName,
      email: shippingInfo.email,
      address: {
        street: shippingInfo.street,
        city: shippingInfo.city,
        zip: shippingInfo.zip,
        country: shippingInfo.country
      },
      items: cart.map(item => ({
        name: item.name,
        quantity: item.quantity,
        price: item.price * currencyMap[currency].rate
      })),
      currency: currency,
      totalAmount: formattedTotal
    };

    try {
      const response = await fetch(APPS_SCRIPT_URL, {
        method: 'POST',
        mode: 'cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload),
      });

      const result = await response.json();

      if (result.checkoutUrl) {
        setCheckoutUrl(result.checkoutUrl);
        setOrderId(result.orderId || `ORD-${Date.now()}`);
        // Sandbox safe redirect using new tab
        window.open(result.checkoutUrl, '_blank');
      } else {
        throw new Error('No checkout URL received');
      }
    } catch (error) {
      console.error('Payment Error:', error);
      setPollError('Payment initialization failed. Please check your connection and try again.');
    } finally {
      setIsProcessing(false);
    }
  };

  const checkStatus = async () => {
    if (!orderId) return;
    setIsPolling(true);
    setPollError(null);
    try {
      const response = await fetch(`${APPS_SCRIPT_URL}?orderId=${orderId}`, {
        method: 'GET',
        mode: 'cors'
      });
      const result = await response.json();
      if (result.status === 'paid') {
        setPaymentStatus('paid');
        clearCart();
        setTimeout(() => navigate('/success'), 2000);
      } else if (result.status === 'open' || result.status === 'pending') {
        setPollError('Payment is still pending. Please ensure you have completed the transaction in the payment window.');
      } else if (result.status === 'failed' || result.status === 'expired' || result.status === 'canceled') {
        setPollError(`Payment ${result.status}. The order could not be completed. Please try again or contact support.`);
      } else {
        setPollError('Payment status could not be confirmed yet. Please complete the transaction.');
      }
    } catch (error) {
      console.error('Status Check Error:', error);
      setPollError('Could not verify payment status due to a connection error. Please try clicking the button again.');
    } finally {
      setIsPolling(false);
    }
  };

  if (cart.length === 0 && !orderId) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col">
        <Header />
