const CartContext = createContext<CartContextType | undefined>(undefined);
const ReviewsContext = createContext<ReviewsContextType | undefined>(undefined);

interface CookieSettings {
  essential: boolean;
  analytics: boolean;
  marketing: boolean;
  consented: boolean;
}

const CookieContext = createContext<{
  cookies: CookieSettings;
  updateCookies: (newSettings: Partial<CookieSettings>) => void;
  showManager: boolean;
  setShowManager: (show: boolean) => void;
} | undefined>(undefined);

const CookieProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [cookies, setCookies] = useState<CookieSettings>(() => {
    const saved = localStorage.getItem('qr_cookie_consent');
    return saved ? JSON.parse(saved) : { essential: true, analytics: false, marketing: false, consented: false };
  });
  const [showManager, setShowManager] = useState(false);

  const updateCookies = (newSettings: Partial<CookieSettings>) => {
    const updated = { ...cookies, ...newSettings, consented: true };
    setCookies(updated);
    localStorage.setItem('qr_cookie_consent', JSON.stringify(updated));
  };

  return (
    <CookieContext.Provider value={{ cookies, updateCookies, showManager, setShowManager }}>
      {children}
    </CookieContext.Provider>
  );
};

const useCookies = () => {
  const context = useContext(CookieContext);
  if (!context) throw new Error('useCookies must be used within a CookieProvider');
  return context;
};

const ReviewsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [dynamicReviews, setDynamicReviews] = useState<Record<string, Review[]>>(() => {
    const saved = localStorage.getItem('qr_dynamic_reviews');
    return saved ? JSON.parse(saved) : {};
  });

  const [deletedReviewIds, setDeletedReviewIds] = useState<Set<string>>(() => {
    const saved = localStorage.getItem('qr_deleted_reviews');
    return saved ? new Set(JSON.parse(saved)) : new Set();
  });

  useEffect(() => {
    localStorage.setItem('qr_dynamic_reviews', JSON.stringify(dynamicReviews));
  }, [dynamicReviews]);

  useEffect(() => {
    localStorage.setItem('qr_deleted_reviews', JSON.stringify(Array.from(deletedReviewIds)));
  }, [deletedReviewIds]);

  const getReviewsForProduct = (productId: string) => {
    const product = PRODUCTS.find(p => p.id === productId);
    const mockReviews = product?.reviews || [];
    const filteredMock = mockReviews.filter(r => !deletedReviewIds.has(r.id));
    const added = dynamicReviews[productId] || [];
    return [...added, ...filteredMock];
  };

  const addReview = (productId: string, review: Review) => {
    setDynamicReviews(prev => ({
      ...prev,
      [productId]: [review, ...(prev[productId] || [])]
    }));
  };

  const deleteReview = async (productId: string, reviewId: string) => {
    try {
      await fetch(FEEDBACK_API_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ 
          action: 'delete', 
          reviewId: reviewId, 
          productId: productId,
          password: 'QrSortable2024' 
        }),
      });
    } catch (e) {
      console.error('Failed to sync deletion with database:', e);
    }

    if (dynamicReviews[productId]?.some(r => r.id === reviewId)) {
      setDynamicReviews(prev => ({
        ...prev,
        [productId]: prev[productId].filter(r => r.id !== reviewId)
      }));
    } else {
      setDeletedReviewIds(prev => {
        const next = new Set(prev);
        next.add(reviewId);
        return next;
      });
    }
  };

  return (
    <ReviewsContext.Provider value={{ getReviewsForProduct, addReview, deleteReview }}>
      {children}
    </ReviewsContext.Provider>
  );
};

const useReviews = () => {
  const context = useContext(ReviewsContext);
  if (!context) throw new Error('useReviews must be used within a ReviewsProvider');
  return context;
};

const CartProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const updateQuantity = (productId: string, quantity: number) => {
    if (quantity < 1) return;
    setCart(prev => prev.map(item => item.id === productId ? { ...item, quantity } : item));
  };

  const toggleCart = () => setIsCartOpen(!isCartOpen);
  const clearCart = () => setCart([]);

  const cartTotal = useMemo(() => cart.reduce((total, item) => total + (item.price * item.quantity), 0), [cart]);

  return (
    <CartContext.Provider value={{ cart, isCartOpen, addToCart, removeFromCart, updateQuantity, toggleCart, cartTotal, clearCart }}>
      {children}
    </CartContext.Provider>
  );
};

const useCart = () => {
  const context = useContext(CartContext);
  if (!context) throw new Error('useCart must be used within a CartProvider');
  return context;
};

