const FeedbackSection: React.FC<{ productId: string }> = ({ productId }) => {
  const { getReviewsForProduct, addReview, deleteReview } = useReviews();
  const reviews = getReviewsForProduct(productId);

  const [isFormOpen, setIsFormOpen] = useState(false);
  const [newReview, setNewReview] = useState({ name: '', email: '', rating: 5, comment: '' });
  const [isSending, setIsSending] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [adminPassword, setAdminPassword] = useState('');
  const [passwordError, setPasswordError] = useState(false);

  const avgRating = calculateAverageRating(reviews);

  const handleDeleteAttempt = (id: string) => {
    setDeletingId(id);
    setAdminPassword('');
    setPasswordError(false);
  };

  const confirmDelete = async () => {
    if (adminPassword === "QrSortable2024") {
      await deleteReview(productId, deletingId!);
      setDeletingId(null);
      setAdminPassword('');
      setPasswordError(false);
    } else {
      setPasswordError(true);
      setTimeout(() => setPasswordError(false), 500);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSending(true);

    const payload = {
      productId,
      name: newReview.name,
      email: newReview.email,
      rating: newReview.rating,
      comment: newReview.comment
    };

    try {
      await fetch(FEEDBACK_API_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload),
      });

      const review: Review = {
        id: Math.random().toString(36).substr(2, 9),
        author: newReview.name || 'Anonymous',
        email: newReview.email,
        rating: newReview.rating,
        comment: newReview.comment,
        date: 'Just now'
      };

      addReview(productId, review);
      setSubmitted(true);

      setTimeout(() => {
        setSubmitted(false);
        setIsFormOpen(false);
        setNewReview({ name: '', email: '', rating: 5, comment: '' });
      }, 3000);
    } catch (error) {
      console.error('Submission failed:', error);
      alert('Error sending feedback. Please try again.');
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="mt-24 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24 border-t border-gray-200">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 mb-16">
        <div>
          <h2 className="text-5xl font-black mb-4 flex items-center">
            <MessageSquare className="h-10 w-10 mr-4 text-[#FDB623]" /> Feedback
          </h2>
          <div className="flex items-center space-x-6">
            <p className="text-2xl text-gray-500 font-bold">What our customers are saying.</p>
            <div className="h-8 w-[2px] bg-gray-200 hidden md:block"></div>
            <StarRating rating={avgRating} showLabel count={reviews.length} size={28} />
          </div>
        </div>
        <div className="flex items-center space-x-4">
          {!isFormOpen && !submitted && (
            <button 
              onClick={() => setIsFormOpen(true)}
              className="bg-black text-white px-10 py-5 rounded-[1.5rem] font-black text-2xl hover:bg-[#FDB623] hover:text-black transition-all shadow-xl active:scale-95"
            >
              Leave a Review
            </button>
          )}
        </div>
      </div>

      {isFormOpen && (
        <div className="bg-white rounded-[3rem] p-10 shadow-2xl border-4 border-[#FDB623]/20 mb-16 animate-in slide-in-from-top-10 duration-500">
          <div className="flex justify-between items-start mb-8">
            <h3 className="text-3xl font-black">Write Your Review</h3>
            <button onClick={() => setIsFormOpen(false)} className="text-gray-400 hover:text-black" disabled={isSending}><X className="h-8 w-8" /></button>
          </div>

          {submitted ? (
            <div className="py-12 text-center space-y-6">
               <div className="bg-green-100 p-8 rounded-full w-fit mx-auto">
                 <Check className="h-20 w-20 text-green-500" />
               </div>
               <div className="space-y-4">
                 <p className="text-3xl font-black">Feedback Sent!</p>
                 <p className="text-xl text-gray-600 font-bold max-w-md mx-auto leading-relaxed">
                   Your review helps us improve the QrSortable experience.
                 </p>
               </div>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <label className="text-xl font-black block">Your Name *</label>
                  <input 
                    type="text" 
                    value={newReview.name}
                    onChange={e => setNewReview({...newReview, name: e.target.value})}
                    placeholder="E.g. John Doe"
                    required
                    disabled={isSending}
                    className="w-full border-2 border-gray-100 bg-gray-50 rounded-2xl p-5 text-xl font-bold outline-none focus:ring-4 focus:ring-[#FDB623]/20 disabled:opacity-50"
                  />
                </div>
                <div className="space-y-4">
                  <label className="text-xl font-black block">Email Address *</label>
                  <input 
                    type="email" 
                    value={newReview.email}
                    onChange={e => setNewReview({...newReview, email: e.target.value})}
                    placeholder="john@example.com"
                    required
                    disabled={isSending}
                    className="w-full border-2 border-gray-100 bg-gray-50 rounded-2xl p-5 text-xl font-bold outline-none focus:ring-4 focus:ring-[#FDB623]/20 disabled:opacity-50"
                  />
                </div>
                <div className="space-y-4 md:col-span-2">
                  <label className="text-xl font-black block">Rating</label>
                  <div className="flex space-x-2">
                    {[1, 2, 3, 4, 5].map(starValue => (
                      <button 
                        key={starValue} 
                        type="button" 
                        disabled={isSending}
                        onClick={() => setNewReview({...newReview, rating: starValue})}
                        className="transition-transform active:scale-90 disabled:opacity-50"
                      >
                        <Star className={`h-10 w-10 ${starValue <= newReview.rating ? 'text-[#FDB623] fill-current' : 'text-gray-200'}`} />
                      </button>
                    ))}
                  </div>
                </div>
              </div>
              <div className="space-y-4">
                <label className="text-xl font-black block">Comment</label>
                <textarea 
                  value={newReview.comment}
                  onChange={e => setNewReview({...newReview, comment: e.target.value})}
                  placeholder="Tell us about your organization journey..."
                  required
                  rows={4}
                  disabled={isSending}
                  className="w-full border-2 border-gray-100 bg-gray-50 rounded-2xl p-5 text-xl font-bold outline-none focus:ring-4 focus:ring-[#FDB623]/20 disabled:opacity-50"
                />
              </div>
              <button 
                type="submit" 
                disabled={isSending}
                className="w-full bg-[#FDB623] text-black py-6 rounded-[2rem] font-black text-2xl hover:bg-yellow-400 shadow-xl transition-all flex items-center justify-center space-x-3 disabled:opacity-75"
              >
                {isSending ? (
                  <>
                    <Loader2 className="h-7 w-7 animate-spin" />
                    <span>Sending...</span>
                  </>
                ) : (
                  <span>Submit Feedback</span>
                )}
              </button>
            </form>
          )}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        {reviews.map((review) => (
          <div key={review.id} className="group bg-white rounded-[2.5rem] p-10 shadow-lg border border-gray-100 flex flex-col hover:border-[#FDB623]/30 transition-all relative h-full">
            {deletingId === review.id && (
              <div className="absolute inset-0 z-30 bg-white/95 backdrop-blur-sm rounded-[2.5rem] flex flex-col items-center justify-center p-8 space-y-6 animate-in fade-in duration-300">
                 <div className="bg-red-50 p-4 rounded-full text-red-500">
                    <Trash2 className="h-8 w-8" />
                 </div>
                 <div className="text-center">
                    <p className="text-2xl font-black text-gray-900">Admin Authentication</p>
                    <p className="text-lg text-gray-500 font-bold">Please enter the password to delete.</p>
                 </div>
                 <div className="w-full max-w-xs space-y-4">
                    <input 
                      type="password"
                      value={adminPassword}
                      onChange={(e) => setAdminPassword(e.target.value)}
                      placeholder="Enter Password"
                      className={`w-full bg-gray-100 border-2 ${passwordError ? 'border-red-400' : 'border-transparent'} rounded-2xl p-4 text-xl font-bold text-center focus:border-[#FDB623] transition-all outline-none`}
                      autoFocus
                    />
                    <div className="flex gap-4">
                       <button onClick={() => setDeletingId(null)} className="flex-1 py-3 font-black text-lg text-gray-400 hover:text-black">Cancel</button>
                       <button onClick={confirmDelete} className="flex-1 bg-black text-white py-3 rounded-xl font-black text-lg hover:bg-red-500 transition-colors">Delete</button>
                    </div>
                 </div>
              </div>
            )}

            <div className="flex justify-between items-start mb-6">
              <div className="flex items-center space-x-4">
                <div className="bg-gray-100 p-4 rounded-full">
                  <User className="h-8 w-8 text-[#FDB623]" />
                </div>
                <div>
                  <p className="text-2xl font-black text-gray-900">{review.author}</p>
                  <p className="text-lg text-gray-400 font-bold">{review.date}</p>
                </div>
              </div>
              <div className="flex items-center space-x-4">
                <div className="flex">
                  {[...Array(5)].map((_, i) => (
                    <Star key={i} className={`h-6 w-6 ${i < review.rating ? 'text-[#FDB623] fill-current' : 'text-gray-200'}`} />
                  ))}
                </div>
                <button 
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    handleDeleteAttempt(review.id);
                  }}
                  className="p-3 text-gray-300 hover:text-red-500 transition-all hover:scale-125 cursor-pointer flex items-center justify-center"
                  title="Delete Feedback"
                >
                  <Trash2 className="h-7 w-7" />
                </button>
              </div>
            </div>

            <p className="text-2xl text-gray-600 font-medium leading-relaxed mb-8 flex-grow">
              "{review.comment}"
            </p>
          </div>
        ))}
        {reviews.length === 0 && (
          <div className="col-span-full py-12 text-center text-gray-400">
            <MessageSquare className="h-16 w-16 mx-auto mb-4 opacity-20" />
            <p className="text-2xl font-bold">No reviews yet. Be the first!</p>
          </div>
        )}
      </div>
    </div>
  );
};

