                   )}
                </div>
                <div className="space-y-4">
                  <h2 className="text-4xl font-black">
                    {paymentStatus === 'paid' ? 'Payment Confirmed!' : 'Waiting for Payment'}
                  </h2>
                  <p className="text-xl text-gray-500 font-bold max-w-md mx-auto">
