                        <input type="text" placeholder="Netherlands" required value={shippingInfo.country} onChange={e => setShippingInfo({...shippingInfo, country: e.target.value})} className="w-full border-2 border-gray-100 bg-gray-50 rounded-2xl px-4 py-5 text-xl font-bold outline-none focus:ring-4 focus:ring-[#FDB623]/20" />
