      const data = await response.json();
      // Data is expected to be an array of reviews. 
      // Each review should have { name, product, rating, comment, date, etc }
      // We filter by the current product name as requested.
      const filtered = (data || []).filter((r: any) => r.product === product.name);

      // Adapt API data to local Review interface
