            <ShieldCheck className="h-10 w-10" />
          </div>

          <div className="flex-1 text-center md:text-left">
            <h2 className="text-3xl font-black mb-4">We respect your privacy</h2>
            <p className="text-xl text-gray-400 font-bold leading-relaxed mb-8">
              We use cookies to enhance your experience, serve personalized content, and analyze our traffic. Your choices help us provide a safer, faster organization experience.
            </p>

            {showManager ? (
              <div className="space-y-6 mb-8">
                {[
                  { key: 'essential', title: 'Essential', desc: 'Required for site functionality (Cart, Security). Always on.', disabled: true },
                  { key: 'analytics', title: 'Analytics', desc: 'Helps us understand how you use our site to improve the experience.', disabled: false },
                  { key: 'marketing', title: 'Marketing', desc: 'Allows us to show you relevant offers and updates elsewhere.', disabled: false }
                ].map((cat) => (
