                      className={`w-14 h-8 rounded-full relative transition-colors ${cookies[cat.key as keyof CookieSettings] ? 'bg-[#FDB623]' : 'bg-gray-700'} ${cat.disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
                    >
