    <div className="absolute inset-0 overflow-hidden pointer-events-none">
      {dots.map(dot => (
        <div 
          key={dot.id}
          className="floating-dot"
          style={{
            width: `${dot.size}px`,
            height: `${dot.size}px`,
            left: `${dot.left}%`,
            top: `${dot.top}%`,
            opacity: dot.opacity,
            '--duration': `${dot.duration}s`,
            animationDelay: `${dot.delay}s`
          } as React.CSSProperties}
        />
      ))}
    </div>
  );
};

const Header: React.FC = () => {
