                    <span className="text-4xl font-black text-gray-900">{currencyMap[currency].symbol}{formattedTotal}</span>
                    <p className="text-xs text-gray-400 font-black uppercase mt-1">Inclusive of VAT</p>
                  </div>
                </div>
                {!checkoutUrl && (
                  <button 
                    type="submit" 
                    form="checkout-form"
                    disabled={isProcessing}
                    className="w-full bg-black text-white py-6 rounded-[2rem] font-black text-2xl hover:bg-[#FDB623] hover:text-black transition-all flex items-center justify-center disabled:opacity-50 active:scale-95"
