  const [mountTime] = useState(Date.now());
  const [honeypot, setHoneypot] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSending(true);

    // 1. Honeypot check
    if (honeypot) {
      console.warn("Honeypot triggered");
      // Fake success
      setSubmitted(true);
      setTimeout(() => {
        setSubmitted(false);
        setIsFormOpen(false);
      }, 1000);
      setIsSending(false);
      return;
    }

    // 2. Bot Timer (2 seconds)
    if (Date.now() - mountTime < 2000) {
      console.warn("Submission too fast");
      setIsSending(false);
      return;
    }

    // 3. Rate Limiting (3 per minute for feedback)
    if (!checkRateLimit('feedback_rate_limit', 3, 60000)) {
      alert("You are submitting feedback too frequently. Please wait a minute.");
      setIsSending(false);
      return;
    }

    const payload = {
      name: newReview.name,
      product: product.name,
      email: newReview.email,
      rating: newReview.rating,
      comment: newReview.comment
    };

