            className={`${star <= Math.round(rating) ? 'text-[#FDB623] fill-current' : 'text-gray-200'}`} 
          />
        ))}
      </div>
      {showLabel && (
        <span className="ml-2 text-lg font-black text-gray-900">
          {rating > 0 ? rating : 'New'}
          {count !== undefined && <span className="text-gray-400 font-bold ml-1">({count})</span>}
        </span>
      )}
    </div>
  );
};

