            </div>
          </div>
        </div>
      </div>

      {/* Product Spec */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24 border-t border-gray-200">
        <h2 className="text-4xl font-black mb-12">{t('product', 'specTitle')}</h2>
